	it("resolves an explicit relay target using discarded metadata even when fresh tabs are the default", async () => {
		const livePage = makePage([() => {}]).page;
		const live = makeTarget("PAGE11", livePage);
		const discarded = makeTarget("PAGE12", makePage([() => {}]).page);
